export const rrspRoomReferenceBand=2000;
export const rrspRoomDefinitions={rrspRoomLedgerPlanning:{title:'Reconcile RRSP contribution records on one unchanged deduction-capacity basis',fields:[
  ['rrspRoomCapacity','Reconciled starting deduction capacity (CAD)',18000,0,100000,1000],
  ['rrspRoomUnused','Prior contributions already made but not deducted (CAD)',5000,0,100000,500],
  ['rrspRoomMonthly','New ordinary contribution each modeled month (CAD)',1500,0,10000,100],
  ['rrspRoomMonths','Synthetic months of new contributions',12,1,12,1]
]}};
export function rrspRoomRow(input,month){
  const newContributions=input.rrspRoomMonthly*month,record=input.rrspRoomUnused+newContributions,headroom=input.rrspRoomCapacity-record,overOrdinary=Math.max(0,-headroom);
  return {month,newContributions,record,headroom,withinCapacity:Math.min(record,input.rrspRoomCapacity),withinReference:Math.min(overOrdinary,rrspRoomReferenceBand),aboveReference:Math.max(0,overOrdinary-rrspRoomReferenceBand)};
}
export function rrspRoomAllocation(input){
  const end=rrspRoomRow(input,input.rrspRoomMonths),q=Math.min(10000,input.rrspRoomCapacity,end.record);
  return {q,beforeCapacity:input.rrspRoomCapacity,beforeRecord:end.record,afterCapacity:input.rrspRoomCapacity-q,afterRecord:end.record-q,headroom:end.headroom};
}
export function rrspRoomResult(kind,input){
  if(kind!=='rrspRoomLedgerPlanning')throw Error('Unknown RRSP room topic.');
  const opening=rrspRoomRow(input,0),end=rrspRoomRow(input,input.rrspRoomMonths),allocation=rrspRoomAllocation(input),months=Array.from({length:input.rrspRoomMonths+1},(_,i)=>i),partitionMonths=[...new Set([0,Math.min(3,input.rrspRoomMonths),Math.min(6,input.rrspRoomMonths),Math.min(9,input.rrspRoomMonths),input.rrspRoomMonths])];
  const monthLabel=month=>month?'Month '+month:'Opening';
  return {metrics:[['Opening signed ordinary contribution headroom',opening.headroom,'money'],['Ending signed ordinary contribution headroom',end.headroom,'money'],['Ending combined undeducted contribution record',end.record,'money']],note:'Invented record example in CAD, on a single frozen deduction-capacity basis. Prior undeducted contributions have already been deposited; they are not unfilled contribution room or current account market value. Each new monthly contribution occurs after the reconciled starting snapshot and is not already included in the prior record. No deduction claim occurs in the monthly ledger. Negative headroom means the contribution record exceeds ordinary capacity; the display does not authorize that schedule. The separate CAD 2,000 reference assumes the statutory prior-taxation-year age condition and all other relevant conditions are satisfied; it does not determine eligibility or additional deductible room. No tax, penalty, refund or corrective withdrawal is calculated. There are no new-year room additions, reassessments, withdrawals, first-60-day prior-year allocations, HBP/LLP repayments, PRPP/SPP transactions, mandatory group-plan amounts, special transfers or historical adjustments. Months are synthetic and do not represent a filing calendar.',charts:[
    {id:'rrsp-room-opening-bridge',type:'waterfall',title:'Subtract contributions already made before planning any new deposit',unit:'money',unitLabel:'CAD on the reconciled starting record basis',rows:[{label:'Starting deduction capacity',value:input.rrspRoomCapacity},{label:'Prior undeducted contributions',value:-input.rrspRoomUnused}],totalLabel:'Opening signed ordinary headroom',note:'Ordinary headroom equals starting deduction capacity minus prior contributions already made but not deducted. At the defaults, CAD 18,000 minus CAD 5,000 leaves CAD 13,000 for new ordinary contributions on this frozen basis. A negative result is retained as an overage indicator, rather than being hidden by a zero floor. These inputs must refer to compatible records and dates.'},
    {id:'rrsp-room-monthly-record',type:'line',title:'New contributions increase the record even when the deduction is deferred',unit:'money',unitLabel:'CAD of contribution records and capacity; no investment account values',xLabel:'Synthetic month',xTicks:months.filter(m=>m===0||m===input.rrspRoomMonths||m%3===0).map(value=>({value,label:monthLabel(value)})),series:[{name:'Combined undeducted contribution record',rows:months.map(x=>({x,label:monthLabel(x),value:rrspRoomRow(input,x).record}))},{name:'Frozen ordinary deduction capacity',dash:true,rows:months.map(x=>({x,label:monthLabel(x),value:input.rrspRoomCapacity}))},{name:'Capacity plus conditional $2,000 reference',dash:true,rows:months.map(x=>({x,label:monthLabel(x),value:input.rrspRoomCapacity+rrspRoomReferenceBand}))}],note:'The rising record is prior undeducted contributions plus cumulative new contributions, with no current deduction claim. The horizontal lines are two different references. The upper line does not enlarge deductible capacity or grant new annual room. Its applicability is assumed for an adult who turned 18 in an earlier taxation year; full statutory excess-tax calculations need additional facts. The chart does not establish a tax-free contribution entitlement.'},
    {id:'rrsp-room-record-partition',type:'stackbar',title:'Separate the contribution record into three non-overlapping reference bands',unit:'money',unitLabel:'CAD of combined undeducted contributions at each snapshot',seriesNames:['Within ordinary capacity','Beyond capacity, within conditional $2,000 band','Above conditional reference'],rows:partitionMonths.map(month=>{const row=rrspRoomRow(input,month);return {label:monthLabel(month),values:[row.withinCapacity,row.withinReference,row.aboveReference]};}),note:'Each stacked bar sums to the contribution record at that snapshot. Snapshots repeat earlier deposits and must not be added together. At default Month 12, CAD 18,000 is within capacity, CAD 2,000 is beyond capacity within the conditional reference, and CAD 3,000 is above that reference: CAD 23,000 altogether. The second band is not extra deductible room, and the third is not an assessed taxable-excess amount. A zero value in either band does not establish that no tax is payable.'},
    {id:'rrsp-room-deduction-allocation',type:'groupbar',title:'An illustrative deduction allocation reduces both comparable records',unit:'money',unitLabel:'CAD in a paired bookkeeping illustration; separate from the monthly schedule',seriesNames:['Before allocation','After illustrative allocation'],rows:[{label:'Unallocated model capacity',values:[allocation.beforeCapacity,allocation.afterCapacity]},{label:'Unallocated contributions',values:[allocation.beforeRecord,allocation.afterRecord]}],note:'The illustrative allocation q is the smaller of CAD 10,000, starting capacity and the ending contribution record: CAD '+allocation.q.toLocaleString('en-CA')+' for these inputs. Subtract q from both records. Their difference remains CAD '+allocation.headroom.toLocaleString('en-CA')+'. This identity does not establish an eligible claim, issue a new CRA limit or calculate next-year room. Subtracting a claim only from the contribution record while keeping the comparable capacity unchanged would falsely recreate room. This illustration is not a new cash deposit or a cash refund.'},
    {id:'rrsp-room-contribution-grid',type:'heatmap',signed:true,compactValues:false,title:'Compare contribution sizes without hiding a negative remaining amount',unit:'money',unitLabel:'Signed ordinary headroom in CAD; columns replace monthly contributions',columns:['$500','$1,000','$1,500','$2,000'],rows:[3,6,9,12].map(month=>({label:'Month '+month,values:[500,1000,1500,2000].map(rrspRoomMonthly=>rrspRoomRow({...input,rrspRoomMonthly},month).headroom)})),note:'Each cell is an independent scenario using the same starting capacity and prior undeducted record. Rows replace the selected horizon and columns replace the monthly contribution. Positive means capacity remains on this frozen basis; zero means it is exactly filled; negative shows the amount beyond ordinary capacity. Cells do not add the CAD 2,000 reference to room and do not calculate tax. No new-year capacity is generated across the synthetic months.'}
  ]};
}
